/* Signature Model Linguistic Coverage Database Names Database — name-meaning lookup demo (jahdb-demo-1.0)
 * RUN ON PC: save as demo.js, then run:  node demo.js [name]
 * RUN IN BROWSER: paste into the console and press Enter. */
var TABLE = {"LINGUA-500": "Coverage-numbered name: '500 languages'.", "XVERSE": "X-prefixed name: 'cross-verse', the multilingual verse benchmark.", "POLYGLOT-QA": "Descriptive benchmark name: 'polyglot question answering'.", "TONGUE-TIDE": "Evocative benchmark name in the FLORES style.", "BABBLE-100": "Playful coverage-numbered name: '100 languages of babble'.", "XROADS": "X-prefixed name: 'crossroads', the code-switching benchmark.", "LINGUA-500-R": "Signature revisited form.", "XVERSE v2": "Signature versioned form.", "POLYGLOT-QA-XL": "Signature extended form.", "TONGUE-TIDE-100": "Signature coverage-numbered form."};
function lookup(q){
  q=String(q||'').toLowerCase().trim();
  var keys=Object.keys(TABLE);
  for(var i=0;i<keys.length;i++){ if(keys[i].toLowerCase()===q) return keys[i]+' — '+TABLE[keys[i]]; }
  var hits=keys.filter(function(k){return k.toLowerCase().indexOf(q)>=0;});
  if(!hits.length) return 'No match for "'+q+'". Try: '+keys.slice(0,5).join(', ');
  return hits.map(function(k){return k+' — '+TABLE[k];}).join('\n');
}
var q=(typeof process!=='undefined'&&process.argv[2])||'LINGUA-500';
console.log(lookup(q));

